  "context_conversations.cs.jinja":
    "{% if is_overview_mode %}SHRNUTÍ ROZHOVORŮ:{% else %}PŘEPISY ROZHOVORŮ:{% endif %}\n{% if conversations|length == 0 %}\nUživatel zatím nepřidal žádné rozhovory. Jemně ho vybídni, ať nějaké přidá výběrem rozhovorů v postranním panelu.\n{% else %}\n   {% for conversation in conversations %}\n<conversation>\n   <name>{{ conversation.name }}</name>\n   <tags>{{ conversation.tags }}</tags>\n   <date>{{ conversation.created_at }}</date>\n   <duration>{{ conversation.duration }}</duration>\n   {% if conversation.summary %}\n   <summary>\n   {{ conversation.summary }}\n   </summary>\n   {% else %}\n   <transcript>\n   {{ conversation.transcript }}\n   </transcript>\n   {% endif %}\n   {% if conversation.artifacts %}\n   <artifacts>\n      {% for artifact in conversation.artifacts %}\n      <artifact>\n         <key>{{ artifact.key }}</key>\n         <content>{{ artifact.content }}</content>\n      </artifact>\n      {% endfor %}\n   </artifacts>\n   {% endif %}\n</conversation>\n   {% endfor %}\n{% endif %}\n\n",
